1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	
8	/**
9	 * When the request opts into sharing a household ({@code sharesHousehold} true), assigns a
10	 * stable {@code householdId} derived from the normalized last name and address, so every
11	 * owner living together at the same address shares one identifier. Existing owners of the
12	 * same household that do not yet carry an id are back-filled with the same value, so both
13	 * the joining owner and the owner already at that address end up sharing it. Derivation and
14	 * normalization are centralised in {@link Households}, which {@link IdentityKeys} also uses
15	 * so an owner's stored {@code householdId} matches the household component of its identity key.
16	 */
17	public class AssignHousehold {
18	
19	    public void service(@Val OwnerFieldsDto request, @Val Owner owner,
20	            OwnerRepository ownerRepository) {
21	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        String lastName = Households.normalize(owner.getLastName());
25	        String address = AddressNormalizer.normalize(owner.getAddress());
26	        String householdId = Households.idFor(owner.getLastName(), owner.getAddress());
27	        owner.setHouseholdId(householdId);
28	        // Back-fill existing household members so both sides share the identifier.
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.getHouseholdId() == null
31	                    && lastName.equals(Households.normalize(existing.getLastName()))
32	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
33	                existing.setHouseholdId(householdId);
34	                ownerRepository.save(existing);
35	            }
36	        }
37	    }
38	}
