1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code householdSize}: the number of owners sharing this owner's
9	 * {@code householdId} after this create, i.e. every existing member already carrying the
10	 * same id (back-filled by {@link AssignHousehold}) plus this owner. Runs after
11	 * {@link AssignHousehold} but before the owner is saved, so the new owner is counted with
12	 * a {@code +1}. Owners not in a shared household (null {@code householdId}) count as one.
13	 */
14	public class AssignHouseholdSize {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String householdId = owner.getHouseholdId();
18	        if (householdId == null) {
19	            owner.setHouseholdSize(1);
20	            return;
21	        }
22	        int count = 1; // this owner, not yet saved
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (householdId.equals(existing.getHouseholdId())) {
25	                count++;
26	            }
27	        }
28	        owner.setHouseholdSize(count);
29	    }
30	}
