1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's numeric {@code membershipLevel} (1-3) from its create-time
7	 * attributes: start at 1, add 1 when an email is present, add 1 when
8	 * {@code namesakeCount} is 0, capped at 3. Level 4 is reserved for tenure.
9	 */
10	public final class MembershipLevels {
11	
12	    private MembershipLevels() {
13	    }
14	
15	    /** The membership level (1-3) for the given owner. */
16	    public static int forOwner(Owner owner) {
17	        int level = 1;
18	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
19	            level++;
20	        }
21	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
22	            level++;
23	        }
24	        return Math.min(level, 3);
25	    }
26	}
