1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code namesakeCount}: the number of owners that already exist,
9	 * before this create, sharing the same first name and last name compared
10	 * case-insensitively. Runs before the owner is saved, so the new owner is not counted.
11	 */
12	public class AssignNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String firstName = owner.getFirstName();
16	        String lastName = owner.getLastName();
17	        int count = 0;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (equalsIgnoreCase(firstName, existing.getFirstName())
20	                    && equalsIgnoreCase(lastName, existing.getLastName())) {
21	                count++;
22	            }
23	        }
24	        owner.setNamesakeCount(count);
25	    }
26	
27	    private static boolean equalsIgnoreCase(String a, String b) {
28	        return a == null ? b == null : a.equalsIgnoreCase(b);
29	    }
30	}
