1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code possibleDuplicate} / {@code possibleDuplicateOf}: a soft-match
9	 * flag for a new owner that is not a hard duplicate but still looks like one.
10	 *
11	 * <p>A create is only rejected (409) when the new owner's whole {@code identityKey} equals an
12	 * existing owner's (see {@link RequireUniqueIdentity}), so by the time this step runs the new
13	 * owner is guaranteed not to be a hard duplicate. Here we flag the weaker signal: an existing
14	 * owner that shares the same {@code lastName} (compared case-insensitively) and the same
15	 * {@code postcode}. When one is found the owner is still created, but with
16	 * {@code possibleDuplicate} true and {@code possibleDuplicateOf} set to the (lowest) matching
17	 * owner id; otherwise {@code possibleDuplicate} is false and {@code possibleDuplicateOf} is
18	 * left unset.
19	 *
20	 * <p>Runs after {@link BuildOwner} (so the owner's fields are set) and before
21	 * {@link SaveOwner} (so the new owner is not compared against itself).
22	 */
23	public class AssignPossibleDuplicate {
24	
25	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
26	        String lastName = owner.getLastName();
27	        String postcode = owner.getPostcode();
28	        Integer matchId = null;
29	        if (lastName != null && postcode != null && !postcode.isBlank()) {
30	            for (Owner existing : ownerRepository.findAll()) {
31	                if (lastName.equalsIgnoreCase(existing.getLastName())
32	                        && postcode.equals(existing.getPostcode())
33	                        && (matchId == null || existing.getId() < matchId)) {
