package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when a create request's derived {@code identityKey}
 * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) exactly
 * matches an existing owner's. Handled by {@link DuplicateIdentityExceptionHandler},
