		String hc = fetchOwner(createOwnerOk(c)).get("householdId").asText();
		assertNotEquals(ha, hc);
	}

	/** household-duplicate: a second owner with the same lastName+postcode is the same household.
	 *  Without sharesHousehold it is rejected 409; with sharesHousehold it is created as a declared
	 *  member and is NOT flagged as a possible duplicate. */
	@Test
	void householdDuplicateRejectedUnlessDeclared() throws Exception {
		String lastName = uniqueLastName();
		ObjectNode a = ownerNode();
		a.put("lastName", lastName);
		a.put("postcode", "2000");
		createOwnerOk(a);

		// Same household, not declared -> 409.
		ObjectNode b = ownerNode();
		b.put("lastName", lastName);
		b.put("postcode", "2000");
		createOwner(b).andExpect(status().isConflict());

		// Same household, declared -> created and not a suspected duplicate.
		ObjectNode c = ownerNode();
		c.put("lastName", lastName);
		c.put("postcode", "2000");
		c.put("sharesHousehold", true);
		assertFalse(fetchOwner(createOwnerOk(c)).get("possibleDuplicate").asBoolean());
	}
}

